5	namespace PhpAiToolkit\PhpStan\Rule\Shared;
6	
7	use PHPStan\Analyser\Scope;
8	
9	/**
10	 * Matches PHPUnit assertion and helper calls made from test cases.
11	 */
12	final class PhpUnitCallTargetMatcher
13	{
14	    /**
15	     * Reports whether the method call target is $this.
16	     */
17	    public function isThisMethodCall(\PhpParser\Node\Expr\MethodCall $node): bool
18	    {
19	        return $node->var instanceof \PhpParser\Node\Expr\Variable
20	            && $node->var->name === 'this';
21	    }
22	
23	    /**
24	     * Reports whether the static call targets PHPUnit Assert or TestCase.
25	     */
26	    public function isStaticCallOnPhpUnitAssert(\PhpParser\Node\Expr\StaticCall $node, Scope $scope): bool
27	    {
28	        if (!$node->class instanceof \PhpParser\Node\Name) {
29	            return false;
30	        }
31	
32	        $className = $node->class->toString();
33	        if (in_array(strtolower($className), ['self', 'static', 'parent'], true)) {
34	            return true;
35	        }
36	
37	        return in_array($scope->resolveName($node->class), [
38	            'PHPUnit\\Framework\\Assert',
39	            'PHPUnit\\Framework\\TestCase',
40	        ], true);
41	    }
42	
43	    /**
44	     * Reports whether the static call targets the current PHPUnit test class surface.
45	     */
46	    public function isStaticCallOnCurrentTestClass(\PhpParser\Node\Expr\StaticCall $node, Scope $scope): bool
47	    {
48	        if (!$node->class instanceof \PhpParser\Node\Name) {
49	            return false;
50	        }
51	
52	        $className = $node->class->toString();
53	        if (in_array(strtolower($className), ['self', 'static', 'parent'], true)) {
54	            return true;
55	        }
56	
57	        return $scope->resolveName($node->class) === 'PHPUnit\\Framework\\TestCase';
58	    }
59	}
