5	namespace PhpAiToolkit\PhpStan\Support;
6	
7	use PHPStan\Analyser\Scope;
8	
9	/**
10	 * Detects whether the current scope is within a test class namespace.
11	 */
12	final class TestClassScope
13	{
14	    /**
15	     * @var list<string>
16	     * @readonly
17	     */
18	    private array $testNamespacePrefixes;
19	
20	    /**
21	     * @var list<string>
22	     * @readonly
23	     */
24	    private array $restrictedTestNamespacePrefixes;
25	
26	    /**
27	     * @param list<string> $testNamespacePrefixes namespace prefixes that identify test classes
28	     * @param list<string> $restrictedTestNamespacePrefixes namespace prefixes for stricter test rules
29	     */
30	    public function __construct(
31	        array $testNamespacePrefixes = ['Tests'],
32	        array $restrictedTestNamespacePrefixes = ['Tests\\Unit', 'Tests\\Integration'],
33	    ) {
34	        $this->testNamespacePrefixes = array_map(
35	            static fn (string $prefix): string => rtrim($prefix, '\\') . '\\',
36	            $testNamespacePrefixes,
37	        );
38	        $this->restrictedTestNamespacePrefixes = array_map(
39	            static fn (string $prefix): string => rtrim($prefix, '\\') . '\\',
40	            $restrictedTestNamespacePrefixes,
41	        );
42	    }
43	
44	    /**
45	     * Determines whether the current scope is inside a test class.
46	     */
47	    public function isTestClass(Scope $scope): bool
48	    {
49	        $classReflection = $scope->getClassReflection();
50	        if ($classReflection === null) {
51	            return false;
52	        }
53	
54	        $className = ltrim($classReflection->getName(), '\\');
55	
56	        foreach ($this->testNamespacePrefixes as $prefix) {
57	            if (str_starts_with($className, $prefix)) {
58	                return true;
59	            }
60	        }
61	
62	        return false;
63	    }
64	
65	    /**
66	     * Determines whether the current scope is inside a restricted test class.
67	     */
68	    public function isRestrictedTestClass(Scope $scope): bool
69	    {
70	        if (!$this->isTestClass($scope)) {
71	            return false;
72	        }
73	
74	        $classReflection = $scope->getClassReflection();
75	        if ($classReflection === null) {
76	            return false;
77	        }
78	
79	        $className = ltrim($classReflection->getName(), '\\');
80	
81	        foreach ($this->restrictedTestNamespacePrefixes as $prefix) {
82	            if (str_starts_with($className, $prefix)) {
83	                return true;
84	            }
85	        }
86	
87	        return false;
88	    }
89	}
