5	namespace PhpAiToolkit\PhpStan\Rule\Shared;
6	
7	use PHPStan\Analyser\Scope;
8	
9	/**
10	 * Resolves direct Foo::class expressions to fully qualified class names.
11	 */
12	final class ClassStringExpressionResolver
13	{
14	    /**
15	     * Returns the fully qualified name represented by a direct class-string expression.
16	     */
17	    public function resolve(\PhpParser\Node\Expr $expression, Scope $scope): ?string
18	    {
19	        if (!$expression instanceof \PhpParser\Node\Expr\ClassConstFetch) {
20	            return null;
21	        }
22	
23	        if (!$expression->name instanceof \PhpParser\Node\Identifier) {
24	            return null;
25	        }
26	
27	        if ($expression->name->toString() !== 'class') {
28	            return null;
29	        }
30	
31	        if (!$expression->class instanceof \PhpParser\Node\Name) {
32	            return null;
33	        }
34	
35	        return $scope->resolveName($expression->class);
36	    }
37	}
