5	namespace PhpAiToolkit\PhpStan\Rule\PhpUnitMockApi;
6	
7	use PhpAiToolkit\PhpStan\Rule\Shared\CallArgumentResolver;
8	use PhpAiToolkit\PhpStan\Rule\Shared\CallMethodNameResolver;
9	use PhpAiToolkit\PhpStan\Rule\Shared\ClassStringExpressionResolver;
10	use PhpAiToolkit\PhpStan\Rule\Shared\PhpUnitCallTargetMatcher;
11	use PHPStan\Analyser\Scope;
12	use PHPStan\Reflection\ReflectionProvider;
13	use PHPStan\Rules\IdentifierRuleError;
14	
15	/**
16	 * Detects prohibited PHPUnit mock API calls in test classes.
17	 */
18	final class PhpUnitMockApiCallInspector
19	{
20	    /** @readonly */
21	    private CallMethodNameResolver $methodNameResolver;
22	
23	    /** @readonly */
24	    private CallArgumentResolver $argumentResolver;
25	
26	    /** @readonly */
27	    private ClassStringExpressionResolver $classStringResolver;
28	
29	    /** @readonly */
30	    private PhpUnitCallTargetMatcher $targetMatcher;
31	
32	    /** @readonly */
33	    private PhpUnitMockApiMethodPolicy $methodPolicy;
34	
35	    /** @readonly */
36	    private PhpUnitMockApiErrorBuilder $errorBuilder;
37	
38	    /**
39	     * Creates an inspector from call parsing, reflection, and policy collaborators.
40	     */
41	    public function __construct(
42	        /** @readonly */
43	        private ReflectionProvider $reflectionProvider,
44	        ?CallMethodNameResolver $methodNameResolver = null,
45	        ?CallArgumentResolver $argumentResolver = null,
46	        ?ClassStringExpressionResolver $classStringResolver = null,
47	        ?PhpUnitCallTargetMatcher $targetMatcher = null,
48	        ?PhpUnitMockApiMethodPolicy $methodPolicy = null,
49	        ?PhpUnitMockApiErrorBuilder $errorBuilder = null,
50	    ) {
51	        $this->methodNameResolver = $methodNameResolver ?? new CallMethodNameResolver();
52	        $this->argumentResolver = $argumentResolver ?? new CallArgumentResolver();
53	        $this->classStringResolver = $classStringResolver ?? new ClassStringExpressionResolver();
54	        $this->targetMatcher = $targetMatcher ?? new PhpUnitCallTargetMatcher();
55	        $this->methodPolicy = $methodPolicy ?? new PhpUnitMockApiMethodPolicy();
56	        $this->errorBuilder = $errorBuilder ?? new PhpUnitMockApiErrorBuilder();
57	    }
58	
59	    /**
60	     * @return list<IdentifierRuleError>
61	     */
62	    public function errors(\PhpParser\Node\Expr $node, Scope $scope): array
63	    {
64	        if ($node instanceof \PhpParser\Node\Expr\MethodCall) {
65	            if (!$this->targetMatcher->isThisMethodCall($node)) {
66	                return [];
67	            }
68	
69	            return $this->errorsForCall(
70	                $this->methodNameResolver->resolve($node->name),
71	                $this->argumentResolver->firstValue($node->args),
72	                $node->getStartLine(),
73	                $scope
74	            );
75	        }
76	
77	        if ($node instanceof \PhpParser\Node\Expr\StaticCall) {
78	            if (!$this->targetMatcher->isStaticCallOnCurrentTestClass($node, $scope)) {
79	                return [];
80	            }
81	
82	            return $this->errorsForCall(
83	                $this->methodNameResolver->resolve($node->name),
84	                $this->argumentResolver->firstValue($node->args),
85	                $node->getStartLine(),
86	                $scope
87	            );
88	        }
89	
90	        return [];
91	    }
92	
93	    /**
94	     * @return list<IdentifierRuleError>
95	     */
96	    public function errorsForCall(?string $methodName, ?\PhpParser\Node\Expr $firstArg, int $line, Scope $scope): array
97	    {
98	        if ($methodName === null) {
99	            return [];
100	        }
101	
102	        if ($this->methodPolicy->isAlwaysProhibited($methodName)) {
103	            return [$this->errorBuilder->prohibitedApi($methodName, $line)];
104	        }
105	
106	        if (!$this->methodPolicy->requiresInterfaceTarget($methodName)) {
107	            return [];
108	        }
109	
110	        if ($firstArg === null) {
111	            return [$this->errorBuilder->requiresLiteralInterface($methodName, $line)];
112	        }
113	
114	        $targetTypeName = $this->classStringResolver->resolve($firstArg, $scope);
115	        if ($targetTypeName === null) {
116	            return [$this->errorBuilder->requiresLiteralInterface($methodName, $line)];
117	        }
118	
119	        if (!$this->reflectionProvider->hasClass($targetTypeName)) {
120	            return [$this->errorBuilder->requiresInterface($methodName, $targetTypeName, $line)];
121	        }
122	
123	        if ($this->reflectionProvider->getClass($targetTypeName)->isInterface()) {
124	            return [];
125	        }
126	
127	        return [$this->errorBuilder->requiresInterface($methodName, $targetTypeName, $line)];
128	    }
129	}
