1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace PhpAiToolkit\PhpStan\Rule\NoBrokenCodeExpectation;
6	
7	use function count;
8	
9	use PhpAiToolkit\PhpStan\Rule\Shared\CallArgumentResolver;
10	use PhpAiToolkit\PhpStan\Rule\Shared\CallMethodNameResolver;
11	use PhpAiToolkit\PhpStan\Rule\Shared\ClassStringExpressionResolver;
12	use PhpAiToolkit\PhpStan\Rule\Shared\PhpUnitCallTargetMatcher;
13	use PHPStan\Analyser\Scope;
14	use PHPStan\Rules\IdentifierRuleError;
15	
16	/**
17	 * Detects PHPUnit exception expectations aimed at types that only broken code produces.
18	 */
19	final class ExpectExceptionCallInspector
20	{
21	    /** @readonly */
22	    private CallMethodNameResolver $methodNameResolver;
23	
24	    /** @readonly */
25	    private CallArgumentResolver $argumentResolver;
26	
27	    /** @readonly */
28	    private ClassStringExpressionResolver $classStringResolver;
29	
30	    /** @readonly */
31	    private PhpUnitCallTargetMatcher $targetMatcher;
32	
33	    /** @readonly */
34	    private BrokenCodeExceptionClassifier $classifier;
35	
36	    /** @readonly */
37	    private NoBrokenCodeExpectationErrorBuilder $errorBuilder;
38	
39	    /**
40	     * Creates an inspector from call parsing, classification, and error-building collaborators.
41	     */
42	    public function __construct(
43	        ?CallMethodNameResolver $methodNameResolver = null,
44	        ?CallArgumentResolver $argumentResolver = null,
45	        ?ClassStringExpressionResolver $classStringResolver = null,
46	        ?PhpUnitCallTargetMatcher $targetMatcher = null,
47	        ?BrokenCodeExceptionClassifier $classifier = null,
48	        ?NoBrokenCodeExpectationErrorBuilder $errorBuilder = null,
49	    ) {
50	        $this->methodNameResolver = $methodNameResolver ?? new CallMethodNameResolver();
51	        $this->argumentResolver = $argumentResolver ?? new CallArgumentResolver();
52	        $this->classStringResolver = $classStringResolver ?? new ClassStringExpressionResolver();
53	        $this->targetMatcher = $targetMatcher ?? new PhpUnitCallTargetMatcher();
54	        $this->classifier = $classifier ?? new BrokenCodeExceptionClassifier();
55	        $this->errorBuilder = $errorBuilder ?? new NoBrokenCodeExpectationErrorBuilder();
56	    }
57	
58	    /**
59	     * @return list<IdentifierRuleError>
60	     */
61	    public function errors(\PhpParser\Node\Expr $node, Scope $scope): array
62	    {
63	        if ($node instanceof \PhpParser\Node\Expr\MethodCall) {
64	            if (!$this->targetMatcher->isThisMethodCall($node)) {
65	                return [];
66	            }
67	
68	            return $this->errorsForCall(
69	                $this->methodNameResolver->resolve($node->name),
70	                $this->argumentResolver->firstValue($node->args),
71	                $node->getStartLine(),
72	                $scope,
73	            );
74	        }
75	
76	        if ($node instanceof \PhpParser\Node\Expr\StaticCall) {
77	            if (!$this->targetMatcher->isStaticCallOnCurrentTestClass($node, $scope)) {
78	                return [];
79	            }
80	
81	            return $this->errorsForCall(
82	                $this->methodNameResolver->resolve($node->name),
83	                $this->argumentResolver->firstValue($node->args),
84	                $node->getStartLine(),
85	                $scope,
86	            );
87	        }
88	
89	        return [];
90	    }
91	
92	    /**
93	     * @return list<IdentifierRuleError>
94	     */
95	    public function errorsForCall(?string $methodName, ?\PhpParser\Node\Expr $firstArg, int $line, Scope $scope): array
96	    {
97	        if ($methodName !== 'expectException' && $methodName !== 'expectExceptionObject') {
98	            return [];
99	        }
100	
101	        if ($firstArg === null) {
102	            return [];
103	        }
104	
105	        $className = $methodName === 'expectException'
106	            ? $this->classStringResolver->resolve($firstArg, $scope)
107	            : $this->expectedObjectClassName($firstArg, $scope);
108	        if ($className === null) {
109	            return [];
110	        }
111	
112	        $reason = $this->classifier->reason($className);
113	        if ($reason === null) {
114	            return [];
115	        }
116	
117	        return [$this->errorBuilder->build($methodName, $className, $reason, $line)];
118	    }
119	
120	    /**
121	     * Returns the single statically known class of an expected exception instance.
122	     */
123	    public function expectedObjectClassName(\PhpParser\Node\Expr $expression, Scope $scope): ?string
124	    {
125	        $classNames = $scope->getType($expression)->getObjectClassNames();
126	
127	        return count($classNames) === 1 ? $classNames[0] : null;
128	    }
129	}
